package com.nihad64.rotam.data.model
import org.json.JSONObject
object PlanJson {
 fun encode(p:Plan)=JSONObject().apply{
 put("id",p.id);put("uid",p.uid);put("title",p.title);put("category",p.category);put("date",p.date);put("startTime",p.startTime);put("endTime",p.endTime);put("endDate",p.endDate)
 put("isCompleted",p.isCompleted);put("isSkipped",p.isSkipped);put("isDeleted",p.isDeleted);put("repeatType",p.repeatType);put("repeatEvery",p.repeatEvery);put("repeatDays",p.repeatDays);put("repeatUntil",p.repeatUntil);put("monthLastDay",p.monthLastDay)
 put("extraData",p.extraData);put("createdAt",p.createdAt);put("seriesId",p.seriesId);put("occurrenceKey",p.occurrenceKey);put("originalDate",p.originalDate);put("reminderEnabled",p.reminderEnabled);put("reminderMinutes",p.reminderMinutes);put("reminderTime",p.reminderTime);put("remindAtEnd",p.remindAtEnd);put("focusSeconds",p.focusSeconds);put("goalId",p.goalId)}
 fun decode(o:JSONObject)=Plan(id=o.optLong("id"),uid=o.nullString("uid")?:java.util.UUID.randomUUID().toString(),title=o.getString("title"),category=Category.fromKey(o.optString("category")).key,date=o.getString("date"),startTime=o.nullString("startTime"),endTime=o.nullString("endTime"),endDate=o.nullString("endDate"),isCompleted=o.optBoolean("isCompleted"),isSkipped=o.optBoolean("isSkipped"),isDeleted=o.optBoolean("isDeleted"),repeatType=o.optString("repeatType","none"),repeatEvery=o.optInt("repeatEvery",1),repeatDays=o.optString("repeatDays"),repeatUntil=o.nullString("repeatUntil"),monthLastDay=o.optBoolean("monthLastDay"),extraData=o.optString("extraData","{}"),createdAt=o.optLong("createdAt",System.currentTimeMillis()),seriesId=o.optLong("seriesId"),occurrenceKey=o.nullString("occurrenceKey"),originalDate=o.nullString("originalDate"),reminderEnabled=o.optBoolean("reminderEnabled"),reminderMinutes=o.optInt("reminderMinutes",15),reminderTime=o.nullString("reminderTime"),remindAtEnd=o.optBoolean("remindAtEnd"),focusSeconds=o.optLong("focusSeconds"),goalId=if(o.has("goalId")&&!o.isNull("goalId"))o.getLong("goalId") else null)
}
fun JSONObject.nullString(k:String):String?=if(!has(k)||isNull(k))null else optString(k).takeIf{it.isNotBlank()&&it!="null"}
